command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8"
$branch="work/unc-network-metadata-sort-20261007"
$expectedBranch="f51edfdb40e066d063c85958601336c1854aeafc"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before cleanup"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $expectedBranch){throw "work branch moved before cleanup"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "work branch delete failed"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "cleanup prune failed"}
& git show-ref --verify --quiet ("refs/remotes/origin/"+$branch)
if($LASTEXITCODE -eq 0){throw "work branch still present after delete"}
Write-Host "UNC_NETWORK_METADATA_WORK_BRANCH_CLEANUP=PASS"
